<?phpsession_start();if (!isset($_SESSION['admin_connecte']) || $_SESSION['admin_connecte'] !== true) {    header("Location: login.php");    exit();}// ==========================================// 1. CONNEXION À LA BASE DE DONNÉES// ==========================================$host = "127.0.0.1";$dbname = "madeb2677953_2zjnm";$user = "madeb2677953_2zjnm";$pass = "wddzero3it";try {    $pdo = new PDO("mysql:host=$host;dbname=$dbname;charset=utf8", $user, $pass);    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);} catch(PDOException $e) {    die("Erreur de connexion à la base de données.");}// ==========================================// 2. LOGIQUE D'EXPORTATION CSV (EXCEL)// ==========================================// Doit être fait avant d'afficher le moindre code HTML !if (isset($_GET['export']) && $_GET['export'] === 'csv') {    $mois_export = isset($_GET['mois']) ? $_GET['mois'] : date('Y-m');        // On récupère les données brutes    $stmt_export = $pdo->prepare("SELECT date_mesure, id_ruche, temperature, humidite, poids FROM mesures WHERE DATE_FORMAT(date_mesure, '%Y-%m') = :mois ORDER BY date_mesure ASC");    $stmt_export->execute(['mois' => $mois_export]);    $lignes = $stmt_export->fetchAll(PDO::FETCH_ASSOC);    // On prépare le navigateur à télécharger un fichier    $nom_fichier = "BEE_WEB_Historique_" . $mois_export . ".csv";    header('Content-Type: text/csv; charset=utf-8');    header('Content-Disposition: attachment; filename="' . $nom_fichier . '"');        // Ouverture du flux    $output = fopen('php://output', 'w');    // Ajout du BOM UTF-8 pour qu'Excel lise bien les accents    fputs($output, "\xEF\xBB\xBF");         // Ligne d'en-tête (Les colonnes)    fputcsv($output, ['Date et Heure', 'ID Ruche', 'Température (°C)', 'Humidité (%)', 'Poids (kg)'], ';');        // On écrit chaque ligne de la base de données    foreach ($lignes as $row) {        $date_formatee = date('d/m/Y H:i:s', strtotime($row['date_mesure']));        fputcsv($output, [            $date_formatee,             "Ruche #" . $row['id_ruche'],             $row['temperature'],             $row['humidite'],             $row['poids']        ], ';');    }        fclose($output);    exit(); // On arrête le code ici pour ne pas afficher le site web dans le fichier Excel}// ==========================================// 3. LECTURE DES PARAMÈTRES EN TEMPS RÉEL// ==========================================$fichier_config = 'config.json';$seuil_froid = 34.5; // Seuils de Leila$seuil_chaud = 35.0; if (file_exists($fichier_config)) {    $config_actuelle = json_decode(file_get_contents($fichier_config), true);    if(isset($config_actuelle['seuil_froid'])) $seuil_froid = floatval($config_actuelle['seuil_froid']);    if(isset($config_actuelle['seuil_chaud'])) $seuil_chaud = floatval($config_actuelle['seuil_chaud']);}// ==========================================// 4. GESTION DU FILTRE PAR MOIS// ==========================================try {    $stmt_mois = $pdo->query("SELECT DISTINCT DATE_FORMAT(date_mesure, '%Y-%m') as mois_valeur, DATE_FORMAT(date_mesure, '%m/%Y') as mois_affichage FROM mesures ORDER BY mois_valeur DESC");    $liste_mois = $stmt_mois->fetchAll(PDO::FETCH_ASSOC);} catch(PDOException $e) {    $liste_mois = []; }$mois_selectionne = isset($_GET['mois']) ? $_GET['mois'] : '';if (empty($mois_selectionne) && !empty($liste_mois)) {    $mois_selectionne = $liste_mois[0]['mois_valeur'];}// ==========================================// 5. RÉCUPÉRATION ET IA D'ANALYSE// ==========================================$donnees_tableau = [];$labels_graph = [];$data_temp_graph = [];$data_poids_graph = [];$mesures = [];$stats = ['moy_temp' => 0, 'moy_poids' => 0, 'nb_alertes' => 0];$alertes_tableau = [];if (!empty($mois_selectionne)) {    $stmt_data = $pdo->prepare("SELECT id_ruche, temperature, humidite, poids, date_mesure FROM mesures WHERE DATE_FORMAT(date_mesure, '%Y-%m') = :mois ORDER BY date_mesure ASC");    $stmt_data->execute(['mois' => $mois_selectionne]);    $mesures = $stmt_data->fetchAll(PDO::FETCH_ASSOC);    $somme_temp = 0; $somme_poids = 0; $compteur = count($mesures);    $donnees_journalieres = [];    foreach ($mesures as $m) {        $somme_temp += floatval($m['temperature']);        $somme_poids += floatval($m['poids']);                $date_obj = new DateTime($m['date_mesure']);        $jour = $date_obj->format('d/m');                if(!isset($donnees_journalieres[$jour])) {            $donnees_journalieres[$jour] = ['temp' => 0, 'poids' => 0, 'count' => 0];        }        $donnees_journalieres[$jour]['temp'] += floatval($m['temperature']);        $donnees_journalieres[$jour]['poids'] += floatval($m['poids']);        $donnees_journalieres[$jour]['count']++;    }    if ($compteur > 0) {        $stats['moy_temp'] = round($somme_temp / $compteur, 1);        $stats['moy_poids'] = round($somme_poids / $compteur, 1);    }    foreach($donnees_journalieres as $jour => $d) {        $labels_graph[] = $jour;        $data_temp_graph[] = round($d['temp'] / $d['count'], 1);        $data_poids_graph[] = round($d['poids'] / $d['count'], 1);    }    // --- LE DÉTECTIVE DYNAMIQUE (Avec les règles de Leila) ---    $etat_temp = [];     $poids_precedent = [];    foreach ($mesures as $m) {        $temp = floatval($m['temperature']);        $poids = floatval($m['poids']);        $ruche = $m['id_ruche'];                if (!isset($etat_temp[$ruche])) $etat_temp[$ruche] = 'normal';                // Alerte Surchauffe        if ($temp >= $seuil_chaud && $etat_temp[$ruche] !== 'chaud') {            $alertes_tableau[] = ['date_alerte' => $m['date_mesure'], 'id_ruche' => $ruche, 'type_alerte' => "🔥 Surchauffe ({$temp}°C)", 'couleur' => 'var(--neon-red)'];            $etat_temp[$ruche] = 'chaud';        }         // Alerte Hypothermie        elseif ($temp <= $seuil_froid && $temp > 0 && $etat_temp[$ruche] !== 'froid') {            $alertes_tableau[] = ['date_alerte' => $m['date_mesure'], 'id_ruche' => $ruche, 'type_alerte' => "❄️ Hypothermie ({$temp}°C)", 'couleur' => '#38bdf8'];            $etat_temp[$ruche] = 'froid';        }         elseif ($temp > $seuil_froid && $temp < $seuil_chaud) {            $etat_temp[$ruche] = 'normal';        }                // Alertes de Poids        if (isset($poids_precedent[$ruche])) {            $chute = $poids_precedent[$ruche] - $poids;                        // Vol (< 5kg final)            if ($poids <= 5.0 && $chute >= 5.0) {                $alertes_tableau[] = ['date_alerte'=>$m['date_mesure'], 'id_ruche'=>$ruche, 'type_alerte'=>"🚨 CHUTE/VOL CRITIQUE ({$poids}kg restants)", 'couleur' => 'var(--neon-red)'];            }            // Récolte (Baisse > 5kg, mais reste > 5kg)            elseif ($chute >= 5.0 && $poids > 5.0) {                $alertes_tableau[] = ['date_alerte'=>$m['date_mesure'], 'id_ruche'=>$ruche, 'type_alerte'=>"🍯 Récolte de miel détectée (-" . round($chute, 1) . "kg)", 'couleur' => 'var(--neon-gold)'];            }            // Essaimage (Baisse entre 1.5 et 5kg)            elseif ($chute >= 1.5 && $chute < 5.0) {                $alertes_tableau[] = ['date_alerte'=>$m['date_mesure'], 'id_ruche'=>$ruche, 'type_alerte'=>"🐝 Essaimage probable (-" . round($chute, 1) . "kg)", 'couleur' => '#f59e0b'];            }        }        $poids_precedent[$ruche] = $poids;    }    $alertes_tableau = array_reverse($alertes_tableau);    $stats['nb_alertes'] = count($alertes_tableau);    $donnees_tableau = array_reverse($mesures);}?><!DOCTYPE html><html lang="fr"><head>    <meta charset="UTF-8">    <meta name="viewport" content="width=device-width, initial-scale=1.0">    <title>BEE WEB // ARCHIVES</title>    <link rel="stylesheet" href="style_app.css">    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>    <style>        .filter-bar { background: rgba(15, 23, 42, 0.8); border: 1px solid rgba(255, 255, 255, 0.1); border-left: 4px solid var(--neon-blue); border-radius: 8px; padding: 15px 25px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 25px; }        select.month-selector { background: rgba(0,0,0,0.5); color: white; border: 1px solid var(--neon-blue); padding: 10px 15px; font-size: 1rem; border-radius: 6px; outline: none; cursor: pointer; font-family: var(--font-tech); }        .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-bottom: 25px; }        .stat-card { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.05); border-radius: 10px; padding: 20px; text-align: center; }        .stat-card i { font-size: 2rem; margin-bottom: 10px; opacity: 0.8; }        .stat-value { font-size: 2.2rem; font-weight: bold; color: #fff; }        .stat-label { font-size: 0.75rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 1px; }        .glass-panel { background: var(--panel-glass); border: 1px solid var(--border-glass); border-radius: 12px; padding: 20px; margin-bottom: 25px; backdrop-filter: blur(10px); }        .cyber-table { width: 100%; border-collapse: collapse; text-align: left; font-size: 0.9rem; }        .cyber-table th { background: rgba(14, 165, 233, 0.1); color: var(--neon-blue); padding: 12px; border-bottom: 2px solid rgba(14, 165, 233, 0.3); font-weight: bold; letter-spacing: 1px; }        .cyber-table td { padding: 12px; border-bottom: 1px solid rgba(255,255,255,0.05); color: #ccc; }        .cyber-table tr:hover td { background: rgba(255,255,255,0.02); color: #fff; }        .table-container { max-height: 400px; overflow-y: auto; }        .table-container::-webkit-scrollbar { width: 8px; }        .table-container::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }        .table-container::-webkit-scrollbar-thumb { background: var(--neon-blue); border-radius: 4px; }                .btn-export { background: rgba(16, 185, 129, 0.1); color: #10b981; padding: 10px 20px; border-radius: 6px; border: 1px solid #10b981; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; gap: 8px; font-family: var(--font-tech); transition: 0.3s;}        .btn-export:hover { background: rgba(16, 185, 129, 0.3); box-shadow: 0 0 10px rgba(16, 185, 129, 0.4); }                .btn-print { background: rgba(255,255,255,0.1); color: white; padding: 10px 20px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.2); cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; gap: 8px; font-family: var(--font-tech); transition: 0.3s;}        .btn-print:hover { background: rgba(255,255,255,0.2); }        @media (max-width: 768px) { .stats-grid { grid-template-columns: 1fr; } .filter-bar { flex-direction: column; gap: 15px; align-items: flex-start; } }    </style></head><body>    <div class="app-wrapper">        <aside class="sidebar">            <div class="sidebar-brand"><i class="fas fa-hexagon-nodes"></i> BEE_WEB</div>            <nav class="sidebar-menu">                <a href="index.php" class="nav-item"><i class="fas fa-th-large"></i> DASHBOARD</a>                <a href="carte.php" class="nav-item"><i class="fas fa-globe-americas"></i> SATELLITE</a>                <a href="monitoring.php" class="nav-item"><i class="fas fa-wave-square"></i> MONITORING AI</a>                <a href="historique.php" class="nav-item active"><i class="fas fa-history"></i> ARCHIVES</a>                <a href="parametres.php" class="nav-item"><i class="fas fa-cogs"></i> SYSTÈME</a>                <a href="logout.php" class="nav-item" style="color: #ef4444; margin-top: 20px; border-top: 1px solid #ef4444; padding-top: 15px;"><i class="fas fa-power-off"></i> DÉCONNEXION</a>            </nav>            <div class="sys-footer">STATUS: ONLINE<br>ENCRYPTION: AES-256</div>        </aside>        <main class="main-content">            <header class="page-header">                <div>                    <h2 style="margin:0;">ARCHIVES <b>SYSTÈME</b></h2>                    <p class="page-subtitle" style="margin-top:5px;">HISTORIQUE ET DÉTECTION INTELLIGENTE</p>                </div>            </header>            <div class="filter-bar">                <div style="display: flex; align-items: center; gap: 15px;">                    <i class="fas fa-calendar-alt" style="color: var(--neon-blue); font-size: 1.5rem;"></i>                    <div>                        <div style="font-size: 0.75rem; color: var(--text-dim); letter-spacing: 1px;">SÉLECTIONNER LA PÉRIODE</div>                        <form method="GET" action="historique.php" id="formMois">                            <select name="mois" class="month-selector" onchange="document.getElementById('formMois').submit();">                                <?php if(empty($liste_mois)): ?>                                    <option value="">Aucune donnée</option>                                <?php else: ?>                                    <?php foreach($liste_mois as $m): ?>                                        <option value="<?php echo $m['mois_valeur']; ?>" <?php if($mois_selectionne == $m['mois_valeur']) echo 'selected'; ?>>                                            <?php echo $m['mois_affichage']; ?>                                        </option>                                    <?php endforeach; ?>                                <?php endif; ?>                            </select>                        </form>                    </div>                </div>                                <div style="display: flex; gap: 10px;">                    <?php if(!empty($mois_selectionne)): ?>                    <a href="historique.php?export=csv&mois=<?php echo $mois_selectionne; ?>" class="btn-export">                        <i class="fas fa-file-csv"></i> EXCEL (CSV)                    </a>                    <?php endif; ?>                    <button class="btn-print" onclick="window.print()">                        <i class="fas fa-print"></i> PDF / IMPRIMER                    </button>                </div>            </div>            <?php if(empty($mois_selectionne)): ?>                <div class="glass-panel" style="text-align: center; padding: 50px;">                    <i class="fas fa-database" style="font-size: 3rem; color: var(--text-dim); margin-bottom: 15px;"></i>                    <h3>BASE DE DONNÉES VIDE</h3>                </div>            <?php else: ?>                <div class="stats-grid">                    <div class="stat-card">                        <i class="fas fa-temperature-half" style="color: var(--neon-blue);"></i>                        <div class="stat-value"><?php echo $stats['moy_temp']; ?>°C</div>                        <div class="stat-label">Moyenne Température</div>                    </div>                    <div class="stat-card">                        <i class="fas fa-weight-hanging" style="color: var(--neon-gold);"></i>                        <div class="stat-value"><?php echo $stats['moy_poids']; ?> kg</div>                        <div class="stat-label">Moyenne Poids</div>                    </div>                    <div class="stat-card" style="border-color: rgba(239,68,68,0.3); background: rgba(239,68,68,0.05);">                        <i class="fas fa-shield-halved" style="color: var(--neon-red);"></i>                        <div class="stat-value" style="color: var(--neon-red);"><?php echo $stats['nb_alertes']; ?></div>                        <div class="stat-label" style="color: var(--neon-red);">Incidents détectés</div>                    </div>                </div>                <div class="glass-panel">                    <h3 style="font-size:1rem; margin-top:0; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 10px; margin-bottom: 20px;">                        <i class="fas fa-chart-line" style="color: var(--neon-blue);"></i> ÉVOLUTION THERMIQUE ET PONDÉRALE                    </h3>                    <div style="height: 350px; position: relative;">                        <canvas id="historiqueChart"></canvas>                    </div>                </div>                <div class="glass-panel" style="border-color: rgba(239, 68, 68, 0.3);">                    <h3 style="font-size:1rem; margin-top:0; border-bottom: 1px solid rgba(239, 68, 68, 0.2); padding-bottom: 10px; margin-bottom: 20px; color: var(--neon-red);">                        <i class="fas fa-robot"></i> JOURNAL DES INCIDENTS                    </h3>                    <div class="table-container" style="max-height: 250px;">                        <table class="cyber-table">                            <thead>                                <tr>                                    <th style="background: rgba(239, 68, 68, 0.1); color: var(--neon-red); border-bottom-color: rgba(239, 68, 68, 0.3);">DATE ET HEURE</th>                                    <th style="background: rgba(239, 68, 68, 0.1); color: var(--neon-red); border-bottom-color: rgba(239, 68, 68, 0.3);">ID RUCHE</th>                                    <th style="background: rgba(239, 68, 68, 0.1); color: var(--neon-red); border-bottom-color: rgba(239, 68, 68, 0.3);">DÉTAIL DE L'INCIDENT</th>                                </tr>                            </thead>                            <tbody>                                <?php if(empty($alertes_tableau)): ?>                                    <tr><td colspan="3" style="text-align:center; color: #10b981; padding: 20px; font-weight: bold;"><i class="fas fa-check-circle"></i> Aucun incident détecté.</td></tr>                                <?php else: ?>                                    <?php foreach($alertes_tableau as $alerte): ?>                                    <tr>                                        <td style="color: white;"><?php echo (new DateTime($alerte['date_alerte']))->format('d/m/Y H:i'); ?></td>                                        <td>#<?php echo $alerte['id_ruche']; ?></td>                                        <td style="color: <?php echo $alerte['couleur']; ?>; font-weight: bold;"><?php echo $alerte['type_alerte']; ?></td>                                    </tr>                                    <?php endforeach; ?>                                <?php endif; ?>                            </tbody>                        </table>                    </div>                </div>                <div class="glass-panel">                    <h3 style="font-size:1rem; margin-top:0; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 10px; margin-bottom: 20px;">                        <i class="fas fa-table" style="color: var(--neon-blue);"></i> REGISTRE DÉTAILLÉ                    </h3>                    <div class="table-container">                        <table class="cyber-table">                            <thead>                                <tr>                                    <th>DATE ET HEURE</th>                                    <th>ID RUCHE</th>                                    <th>TEMPÉRATURE</th>                                    <th>HUMIDITÉ</th>                                    <th>POIDS</th>                                </tr>                            </thead>                            <tbody>                                <?php foreach($donnees_tableau as $ligne): ?>                                <tr>                                    <td><?php echo (new DateTime($ligne['date_mesure']))->format('d/m/Y H:i:s'); ?></td>                                    <td>#<?php echo $ligne['id_ruche']; ?></td>                                    <td><?php echo $ligne['temperature']; ?> °C</td>                                    <td><?php echo $ligne['humidite']; ?> %</td>                                    <td><?php echo $ligne['poids']; ?> kg</td>                                </tr>                                <?php endforeach; ?>                            </tbody>                        </table>                    </div>                </div>            <?php endif; ?>        </main>    </div>    <?php if(!empty($mois_selectionne)): ?>    <script>        const ctx = document.getElementById('historiqueChart').getContext('2d');        const chartLabels = <?php echo json_encode($labels_graph); ?>;        const chartDataTemp = <?php echo json_encode($data_temp_graph); ?>;        const chartDataPoids = <?php echo json_encode($data_poids_graph); ?>;        new Chart(ctx, {            type: 'line',            data: {                labels: chartLabels,                datasets: [                    { label: 'Température Moyenne (°C)', data: chartDataTemp, borderColor: '#0ea5e9', backgroundColor: 'rgba(14, 165, 233, 0.1)', borderWidth: 2, pointBackgroundColor: '#0ea5e9', fill: true, tension: 0.4, yAxisID: 'y' },                    { label: 'Poids Moyen (kg)', data: chartDataPoids, borderColor: '#f59e0b', backgroundColor: 'rgba(245, 158, 11, 0.05)', borderWidth: 2, borderDash: [5, 5], pointBackgroundColor: '#f59e0b', fill: true, tension: 0.4, yAxisID: 'y1' }                ]            },            options: {                responsive: true, maintainAspectRatio: false,                plugins: { legend: { display: true, labels: { color: 'white' } } },                scales: {                    x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#64748b' } },                    y: { position: 'left', title: { display: true, text: 'Température (°C)', color: '#0ea5e9' }, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#64748b' } },                    y1: { position: 'right', title: { display: true, text: 'Poids (kg)', color: '#f59e0b' }, grid: { drawOnChartArea: false }, ticks: { color: '#64748b' } }                }            }        });    </script>    <?php endif; ?></body></html>